const uid=()=>Math.random().toString(36).slice(2,10); const now=new Date(); const iso=d=>d.toISOString().slice(0,10); const today=iso(now); const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
